-- ══════════════════════════════════════════════════════════════════════
-- keyValue content seed — PRODUCTION (vaibhavVivaaha)
--
-- The keyValue table has ONLY three columns: id, keyColumn, valueColumn.
-- There is no isActive / createdAt / createdBy — do not add them to inserts.
--
-- keyColumn has NO UNIQUE INDEX (only PRIMARY on id), so ON DUPLICATE KEY
-- UPDATE does NOT work here — it would silently insert duplicate rows.
-- DELETE-then-INSERT per key is used instead to stay idempotent.
--
-- valueColumn is a json column: MySQL validates it, malformed JSON is rejected.
-- ══════════════════════════════════════════════════════════════════════

START TRANSACTION;

-- FAQ_CONTENT  (12 entries / 6 categories — identical to the shipped copy)
DELETE FROM keyValue WHERE keyColumn = 'FAQ_CONTENT';
INSERT INTO keyValue (keyColumn, valueColumn)
VALUES ('FAQ_CONTENT', '[{"category":"Getting Started","question":"How do I create a profile?","answer":"To create a profile, download our app and tap \\"Sign Up\\". Fill in your basic details, upload photos, and complete your profile information. Make sure to verify your phone number and email for better matches."},{"category":"Getting Started","question":"What information should I include in my profile?","answer":"Include accurate information about yourself including age, education, profession, family details, and preferences. Add recent photos and write a genuine bio to attract compatible matches."},{"category":"Matching","question":"How does the matching system work?","answer":"Our advanced matching algorithm considers your preferences for age, location, education, profession, community, and lifestyle choices to suggest compatible profiles."},{"category":"Matching","question":"Can I filter matches based on my preferences?","answer":"Yes, you can set detailed preferences including age range, height, education, profession, income, location, community, and more to get more relevant matches."},{"category":"Privacy & Safety","question":"How is my personal information protected?","answer":"We use advanced encryption and security measures to protect your data. You can also control what information is visible to others through privacy settings."},{"category":"Privacy & Safety","question":"Can I hide my profile from certain people?","answer":"Yes, you can block specific users or hide your profile from people in your contacts. You can also control who can see your phone number and photos."},{"category":"Communication","question":"How can I contact someone I\'m interested in?","answer":"You can send interest, chat messages, or contact them directly if they have shared their contact information. Premium members get additional communication features."},{"category":"Communication","question":"What should I do if someone is bothering me?","answer":"You can block and report any user who makes you uncomfortable. Our support team reviews all reports and takes appropriate action to ensure a safe environment."},{"category":"Premium Features","question":"What are the benefits of premium membership?","answer":"Premium members get unlimited messaging, advanced search filters, see who viewed their profile, get priority customer support, and can contact members directly."},{"category":"Premium Features","question":"How much does premium membership cost?","answer":"We offer various premium plans starting from affordable monthly subscriptions. Check the upgrade section in settings for current pricing and offers."},{"category":"Account Management","question":"How can I delete my account?","answer":"You can delete your account from Settings > Account Settings > Delete Account. Please note that this action is irreversible and all your data will be permanently removed."},{"category":"Account Management","question":"Can I pause my profile temporarily?","answer":"Yes, you can hide your profile temporarily from Settings. Your profile won\'t appear in searches, but your account and data remain intact."}]');

