-- TERMS_CONTENT  (all 10 sections / 37 paragraphs — identical to the shipped copy)
DELETE FROM keyValue WHERE keyColumn = 'TERMS_CONTENT';
INSERT INTO keyValue (keyColumn, valueColumn)
VALUES ('TERMS_CONTENT', '[{"title":"1. Introduction","content":["Welcome to our matrimonial service. These Terms and Conditions (\\"Terms\\") govern your use of our matrimonial platform, website, and mobile application (collectively, the \\"Service\\") operated by [Company Name] (\\"we,\\" \\"us,\\" or \\"our\\").","By accessing or using our Service, you agree to be bound by these Terms. If you disagree with any part of these terms, then you may not access the Service."],"iconBg":"#fee2e2"},{"title":"2. User Accounts","content":["2.1 Registration: To access our Service, you must register for an account. You must be at least 18 years old to create an account.","2.2 Accuracy: You agree to provide accurate, current, and complete information during registration and to update such information as needed.","2.3 Security: You are responsible for safeguarding your account credentials and for all activities that occur under your account.","2.4 One Account: You may only maintain one active account at any time."],"iconBg":"#dbeafe"},{"title":"3. User Conduct","content":["You agree not to:","• Provide false or misleading information","• Impersonate any person or entity","• Harass, abuse, or harm other users","• Post inappropriate or offensive content","• Solicit money or engage in commercial activities","• Use automated systems to access the Service","• Attempt to gain unauthorized access to other accounts"],"iconBg":"#d1fae5"},{"title":"4. Privacy and Data Protection","content":["4.1 Data Collection: We collect and process personal information as described in our Privacy Policy.","4.2 Profile Visibility: Information in your profile may be visible to other users based on your privacy settings.","4.3 Data Security: We implement appropriate security measures to protect your personal information.","4.4 Third-party Sharing: We do not sell or rent your personal information to third parties without your consent."],"iconBg":"#ede9fe"},{"title":"5. Premium Services and Payments","content":["5.1 Premium Features: We offer premium services that provide additional features and benefits.","5.2 Payments: Premium services require payment of applicable fees. All fees are non-refundable unless stated otherwise.","5.3 Automatic Renewal: Premium subscriptions automatically renew unless cancelled before the renewal date.","5.4 Cancellation: You may cancel your premium subscription at any time through your account settings."],"iconBg":"#fef3c7"},{"title":"6. Intellectual Property","content":["6.1 Our Content: The Service and its original content, features, and functionality are owned by us and are protected by copyright, trademark, and other laws.","6.2 User Content: You retain ownership of content you post, but grant us a license to use, modify, and display it on our platform.","6.3 Restrictions: You may not reproduce, distribute, or create derivative works of our content without permission."],"iconBg":"#e0e7ff"},{"title":"7. Disclaimer and Limitation of Liability","content":["7.1 No Guarantee: We do not guarantee that you will find a suitable match through our Service.","7.2 User Responsibility: You are responsible for your interactions with other users and for verifying the information they provide.","7.3 Service Availability: We do not guarantee uninterrupted or error-free service.","7.4 Limitation: Our liability to you is limited to the amount you paid for premium services, if any."],"iconBg":"#fee2e2"},{"title":"8. Termination","content":["8.1 By You: You may terminate your account at any time by following the deletion process in your settings.","8.2 By Us: We may terminate or suspend your account if you violate these Terms or engage in prohibited conduct.","8.3 Effect: Upon termination, your access to the Service will cease, and we may delete your account and data."],"iconBg":"#f3f4f6"},{"title":"9. Changes to Terms","content":["We reserve the right to modify these Terms at any time. We will notify users of significant changes via the Service or email. Your continued use of the Service after changes constitute acceptance of the new Terms."],"iconBg":"#ffedd5"},{"title":"10. Contact Information","content":["If you have any questions about these Terms and Conditions, please contact us at:","Email: legal@matrimony.com","Phone: +1 (555) 123-4567","Address: [Your Company Address]"],"iconBg":"#ccfbf1"}]');

COMMIT;

-- verify: expect exactly one row each
SELECT keyColumn, COUNT(*) AS rows_, MAX(CHAR_LENGTH(valueColumn)) AS len
FROM keyValue WHERE keyColumn IN ('FAQ_CONTENT','SUPPORT_CONTENT','TERMS_CONTENT')
GROUP BY keyColumn;